contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint lockTime, uint minSum, uint firstValue, uint collectAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (firstValue)); require(firstValue <= 1000000000000000000000000000000);
        require(firstValue > 0);
        require(collectAmt > 0);
        require(address(this).balance >= firstValue);
        require(lockTime <= block.timestamp);

        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(0)); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        c.Put{value: firstValue}(lockTime); if (__ESBMC_reverted()) return;

        (uint unlockBefore, uint balBefore) = c.Acc(address(this)); if (__ESBMC_reverted()) return;

        require(collectAmt <= balBefore);

        bool reverted;
        c.Collect(collectAmt); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        (uint unlockAfter, uint balAfter) = c.Acc(address(this)); if (__ESBMC_reverted()) return;

        bool expectedRevert = !(balBefore >= minSum && block.timestamp > unlockBefore);

        assert(reverted == expectedRevert && (reverted || balAfter == balBefore - collectAmt));
    }

    receive() external payable {}
}

