import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 lockTime, uint256 minSum, uint256 firstValue, uint256 collectAmt) internal {
        firstValue = bound(firstValue, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(firstValue > 0);
        vm.assume(collectAmt > 0);
        vm.assume(address(this).balance >= firstValue);
        vm.assume(lockTime <= block.timestamp);
        try c.SetMinSum(minSum) {} catch { return; }
        try c.SetLogFile(address(0)) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Put{value: firstValue}(lockTime) {} catch { return; }
        uint256 unlockBefore;
        uint256 balBefore;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { unlockBefore = __r0; balBefore = __r1; } catch { return; }
        vm.assume(collectAmt <= balBefore);
        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 unlockAfter;
        uint256 balAfter;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { unlockAfter = __r0; balAfter = __r1; } catch { return; }
        bool expectedRevert = !(balBefore >= minSum && block.timestamp > unlockBefore);
        assertTrue(reverted == expectedRevert && (reverted || balAfter == balBefore - collectAmt));
    }

    function testFuzz_run(uint256 lockTime, uint256 minSum, uint256 firstValue, uint256 collectAmt) public {
        _run(lockTime, minSum, firstValue, collectAmt);
    }

    receive() external payable {}
